package http

import "encoding/json"

// PreviewBridge controls actual authored DOM inside the opaque sandbox. The
// parent retains authentication and explicitly persists edits through the API.
func PreviewBridge(file, parentOrigin string) string {
	settings, _ := json.Marshal(map[string]string{"sourceFile": file, "parentOrigin": parentOrigin})
	return `<script data-studio-studio-bridge>(()=>{const cfg=` + string(settings) + `;` + previewBridge + `})();</script>`
}

const previewBridge = `
const FPS=30;let playing=false,time=0,rate=1,last=0,editing=false,ready=null;
const emit=(type,data)=>parent.postMessage({source:'hf-preview',type,...data},cfg.parentOrigin||'*');
const root=()=>document.querySelector('[data-composition-id]');
const timeline=()=>{const r=root();return r&&(window.__timelines||{})[r.getAttribute('data-composition-id')]};
const duration=()=>{const r=root(),t=timeline(),value=Number(r&&(r.getAttribute('data-duration')||r.getAttribute('data-hf-authored-duration'))||(t&&typeof t.duration==='function'?t.duration():0));return Number.isFinite(value)&&value>0?Math.min(value,120):0};
const selector=e=>{if(e.id&&/^[A-Za-z0-9_-]+$/.test(e.id))return '#'+e.id;const parts=[];while(e&&e!==document.body){let i=1;for(let p=e.previousElementSibling;p;p=p.previousElementSibling)if(p.tagName===e.tagName)i++;parts.unshift(e.tagName.toLowerCase()+':nth-of-type('+i+')');e=e.parentElement}return parts.join(' > ')};
const target=t=>{if(!t||typeof t!=='object')throw Error('target required');let e;if(typeof t.id==='string'&&t.id.length<=200)e=document.getElementById(t.id);if(!e&&typeof t.selector==='string'&&t.selector.length<=1000){const n=t.selectorIndex??0;if(!Number.isInteger(n)||n<0||n>10000)throw Error('selector index invalid');e=document.querySelectorAll(t.selector)[n]}if(!e||['HTML','HEAD','BODY','SCRIPT','STYLE'].includes(e.tagName))throw Error('element absent');return e};
const describe=e=>{const rect=e.getBoundingClientRect(),style=getComputedStyle(e),attributes={};for(const a of [...e.attributes].slice(0,100))attributes[a.name]=a.value;const styles={};for(const k of ['color','background-color','font-family','font-size','font-weight','line-height','letter-spacing','text-align','opacity','position','left','top','width','height','transform','transform-origin','border-radius','display','z-index','translate','rotate','scale','visibility','background-image','background-size','background-position','background-repeat','object-fit','object-position','font-style','text-transform','text-decoration','white-space','padding','margin','border','box-shadow','flex-direction','flex-basis','flex-grow','flex-shrink','box-sizing','min-width','min-height','max-width','max-height','right','bottom','inset','gap','justify-content','align-items','mix-blend-mode','border-width','border-style','border-color','border-top-width','border-top-style','border-top-color','outline-color','overflow','clip-path','filter','backdrop-filter'])styles[k]=style.getPropertyValue(k);return{id:e.id||selector(e),domId:e.id||undefined,selector:selector(e),selectorIndex:0,sourceFile:cfg.sourceFile,key:cfg.sourceFile+':'+selector(e),tag:e.tagName.toLowerCase(),tagName:e.tagName.toLowerCase(),childCount:e.children.length,label:e.getAttribute('data-timeline-label')||e.getAttribute('data-label')||e.id||e.tagName.toLowerCase(),text:e.textContent,attributes,styles,box:{x:rect.x,y:rect.y,width:rect.width,height:rect.height},start:Number(e.getAttribute('data-start')||0),duration:Number(e.getAttribute('data-duration')||duration()),track:Number(e.getAttribute('data-track-index')||0)}};
const clips=()=>[...document.querySelectorAll('[data-start]')].slice(0,1000).map(e=>({...describe(e),compositionId:e.getAttribute('data-composition-id')||undefined,parentCompositionId:e.parentElement?.closest('[data-composition-id]')?.getAttribute('data-composition-id')||undefined,kind:e.hasAttribute('data-composition-id')?'composition':e.tagName.toLowerCase(),assetUrl:e.getAttribute('src')||undefined}));
const publish=()=>{emit('timeline',{durationInFrames:Math.round(duration()*FPS),clips:clips()});const r=root();if(r){const b=r.getBoundingClientRect();emit('stage-size',{width:Number(r.getAttribute('data-width'))||b.width,height:Number(r.getAttribute('data-height'))||b.height})}};
const state=()=>emit('state',{frame:Math.round(time*FPS),isPlaying:playing,playbackRate:rate});
const seek=value=>{time=Math.max(0,Math.min(duration(),Number(value)||0));const t=timeline();if(t&&typeof t.pause==='function')t.pause();if(t&&typeof t.seek==='function')t.seek(time,false);for(const a of document.getAnimations()){a.pause();a.currentTime=time*1000}for(const media of document.querySelectorAll('video,audio')){const start=Number(media.getAttribute('data-start')||0),trim=Number(media.getAttribute('data-playback-start')||media.getAttribute('data-media-start')||0),active=time>=start&&time<start+Number(media.getAttribute('data-duration')||media.duration||0),local=Math.max(0,time-start)+trim;if(Number.isFinite(media.duration)&&Math.abs(media.currentTime-local)>.1)media.currentTime=Math.min(media.duration,local);if(playing&&active){media.playbackRate=rate;media.play().catch(()=>emit('media-autoplay-blocked',{}))}else media.pause()}};
const mutate=(e,ops)=>{if(!Array.isArray(ops)||ops.length<1||ops.length>64)throw Error('operations invalid');for(const o of ops){if(!o||typeof o!=='object'||o.value!=null&&typeof o.value!=='string'||String(o.value??'').length>65536)throw Error('operation invalid');if(o.type==='style'){if(!/^(?:--)?[A-Za-z][A-Za-z0-9_-]{0,99}$/.test(o.property))throw Error('style invalid');if(o.value==null)e.style.removeProperty(o.property);else e.style.setProperty(o.property,o.value)}else if(o.type==='attribute'){if(!/^[A-Za-z][A-Za-z0-9_-]{0,99}$/.test(o.property)||/^on/i.test(o.property)||/^srcdoc$/i.test(o.property))throw Error('attribute invalid');if(o.value==null)e.removeAttribute(o.property);else e.setAttribute(o.property,o.value)}else if(o.type==='text'){if(typeof o.value!=='string')throw Error('text invalid');e.textContent=o.value}else if(o.type==='remove'){if(ops.length!==1)throw Error('remove invalid');e.remove()}else throw Error('operation unsupported')}return e.isConnected?describe(e):null};
window.addEventListener('message',event=>{if(event.source!==parent||cfg.parentOrigin&&event.origin!==cfg.parentOrigin||!event.data||event.data.source!=='hf-parent')return;const m=event.data;if(m.type==='control'){switch(m.action){case'play':if(time>=duration())time=0;playing=true;seek(time);break;case'pause':playing=false;seek(time);break;case'seek':if(Number.isFinite(m.frame))seek(m.frame/FPS);break;case'set-muted':case'set-media-output-muted':for(const media of document.querySelectorAll('video,audio'))media.muted=!!m.muted;break;case'set-volume':if(Number.isFinite(m.volume)&&m.volume>=0&&m.volume<=1)for(const media of document.querySelectorAll('video,audio'))media.volume=m.volume;break;case'set-playback-rate':if(Number.isFinite(m.playbackRate)&&m.playbackRate>0&&m.playbackRate<=4)rate=m.playbackRate;break;case'enable-editing':editing=!!m.enabled;break;case'probe':if(ready)emit('ready',ready);break}state();return}if(m.type!=='edit'||typeof m.requestId!=='string'||m.requestId.length>128)return;try{let data;switch(m.action){case'inspect':data={elements:[...document.querySelectorAll('body *')].filter(e=>!['SCRIPT','STYLE','LINK','META'].includes(e.tagName)).slice(0,1000).map(describe)};break;case'select':data={selection:describe(target(m.target))};break;case'apply':data={selection:mutate(target(m.target),m.operations)};publish();break;case'enable':editing=!!m.enabled;data={enabled:editing};break;default:throw Error('edit action unsupported')}emit('edit-result',{requestId:m.requestId,data})}catch(e){emit('edit-result',{requestId:m.requestId,error:{code:'STUDIO_EDIT_INVALID',message:String(e.message||e)}})}});
document.addEventListener('pointerdown',event=>{if(!editing||!(event.target instanceof Element))return;try{const selected=target({selector:selector(event.target)});event.preventDefault();event.stopPropagation();emit('selection',{selection:describe(selected)})}catch{}},true);
document.addEventListener('keydown',event=>{if(editing)emit('edit-key',{key:event.key,code:event.code,ctrlKey:event.ctrlKey,metaKey:event.metaKey,shiftKey:event.shiftKey})});
let sent=0;const tick=now=>{if(playing&&last){seek(time+(now-last)/1000*rate);if(time>=duration()){playing=false;seek(time)}}last=now;if(now-sent>=1000/FPS){state();sent=now}requestAnimationFrame(tick)};
const start=async()=>{try{await Promise.race([Promise.all([document.fonts.ready,...[...document.querySelectorAll('video,audio')].map(m=>m.readyState>=1?Promise.resolve():new Promise((resolve,reject)=>{m.addEventListener('loadedmetadata',resolve,{once:true});m.addEventListener('error',()=>reject(Error('workspace media unavailable')),{once:true})}))]),new Promise((_,reject)=>setTimeout(()=>reject(Error('workspace readiness timed out')),5000))]);const r=root(),box=r?.getBoundingClientRect(),width=Number(r?.getAttribute('data-width'))||box?.width,height=Number(r?.getAttribute('data-height'))||box?.height;if(!(duration()>0&&width>0&&height>0))throw Error('composition metadata unavailable');ready={durationInFrames:Math.round(duration()*FPS),width,height,sourceFile:cfg.sourceFile,editProtocolVersion:'1'};publish();seek(0);state();emit('ready',ready);requestAnimationFrame(tick)}catch(e){emit('error',{code:'STUDIO_PREVIEW_INVALID',message:String(e.message||e)})}};if(document.readyState==='complete')start();else window.addEventListener('load',start,{once:true});
`
